def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    my_def = sum(1 for a in me if a == 'D')
    if n >= 2 and opp_def == n:
        return 'D'
    if n >= 3 and all(a == 'D' for a in opp[-3:]):
        return 'D'
    no_retaliate = 0
    for i in range(n - 1):
        if me[i] == 'D' and opp[i + 1] == 'C':
            no_retaliate += 1
    if no_retaliate >= 1 and opp_def <= n * 0.1:
        return 'D'
    if n >= 2 and (me[-1] == 'D' or me[-2] == 'D') and opp_def <= n * 0.5:
        return 'C'
    if opp[-1] == 'D' and me[-1] == 'C':
        return 'D'
    if opp[-1] == 'D' and me[-1] == 'D':
        return 'C'
    if my_def == 0 and opp_def == 0 and n >= 5:
        return 'D'
    return 'C'
